param([Parameter(Mandatory=$true)][string]$OutputDirectory,[Parameter(Mandatory=$true)][string]$ResearchDirectory)
$ErrorActionPreference='Stop';if($PSVersionTable.PSVersion.Major -lt 7){throw 'Use pwsh.exe'}
$mtRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'));$mtOut=[IO.Path]::GetFullPath($OutputDirectory);$mtResearch=(Resolve-Path -LiteralPath $ResearchDirectory).Path;$mtAllowed=Join-Path $mtRoot 'reports/m4-crt-matherr'
if(-not $mtOut.StartsWith($mtAllowed+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase) -or -not $mtResearch.StartsWith($mtAllowed+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'Private matherr evidence required'}
$mtName=Split-Path $mtOut -Leaf;if($mtName -notmatch '^[a-z][a-z0-9-]{0,63}$' -or $mtName -match '^(con|prn|aux|nul|com[0-9]|lpt[0-9])$'){throw 'Fresh simple experiment name'}
$mtBuild=Join-Path $mtRoot "build/m4-crt-matherr-$mtName";if((Test-Path -LiteralPath $mtOut) -or (Test-Path -LiteralPath $mtBuild)){throw 'Fresh entire original report/build required'}
function Hash([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
$mtProvider=Join-Path $mtRoot 'local/mw3-staged/Shared_DLLs/MSVCRT.DLL';if((Hash $mtProvider) -ne '2d5670881a6d13a100e37da297f6eeb876f68b63073a28eb5d650625c60f9bf7'){throw 'Exact provider identity required'}
$mtPrep=Get-Content -Raw -LiteralPath (Join-Path $mtResearch 'pins.json')|ConvertFrom-Json;foreach($prop in $mtPrep.files.PSObject.Properties){if((Hash $prop.Name) -ne $prop.Value){throw 'Frozen paired preparation changed'}}
$mtSources=[ordered]@{};foreach($file in @(Get-ChildItem -LiteralPath $PSScriptRoot -File -Recurse|Where-Object {$_.FullName -notmatch '__pycache__'};Get-Item -LiteralPath (Join-Path $mtRoot 'tools/m4-crt/probe_common.hpp'),(Join-Path $mtRoot 'tools/m4-crt/probe_io.hpp'),(Join-Path $mtRoot 'tools/m4-crt-control-integration/reference_x86.asm'),(Join-Path $mtResearch 'pack_spec.hpp'))|Sort-Object FullName){$mtSources[$file.FullName]=Hash $file.FullName}
New-Item -ItemType Directory $mtOut|Out-Null;$mtCopies=[Collections.Generic.List[object]]::new();foreach($path in $mtSources.Keys){$copy=Join-Path (Join-Path $mtOut 'sources') ([IO.Path]::GetRelativePath($mtRoot,$path));New-Item -ItemType Directory -Force (Split-Path $copy)|Out-Null;Copy-Item -LiteralPath $path -Destination $copy;if((Hash $copy) -ne $mtSources[$path]){throw 'Exact literal original source preservation'};$mtCopies.Add(@{original_path=$path;preserved_path=$copy;sha256=$mtSources[$path]})}
$mtCommands=[Collections.Generic.List[object]]::new()
function InvokeTool([string]$Program,[string[]]$Arguments,[string]$Log){$saved=$ErrorActionPreference;$ErrorActionPreference='Continue';try{& $Program @Arguments 2>&1|Tee-Object -FilePath $Log|Out-Null;$exit=$LASTEXITCODE}finally{$ErrorActionPreference=$saved};$mtCommands.Add(@{program=$Program;arguments=$Arguments;exit_code=$exit;log_path=$Log;log_sha256=(Hash $Log)});if($exit -ne 0){throw "Original tool failed $Program exit=$exit"}}
$mtVS='C:/Program Files/Microsoft Visual Studio/18/Community';$mtPassed=$false;$mtFailure=$null
try{
 Import-Module (Join-Path $mtVS 'Common7/Tools/Microsoft.VisualStudio.DevShell.dll');Enter-VsDevShell -VsInstallPath $mtVS -SkipAutomaticLocation -DevCmdArguments '-arch=x86 -host_arch=x64'|Out-Null
 $mtCMake=Join-Path $mtVS 'Common7/IDE/CommonExtensions/Microsoft/CMake/CMake/bin/cmake.exe'
 InvokeTool $mtCMake @('-S',(Join-Path $PSScriptRoot 'original'),'-B',$mtBuild,'-G','Visual Studio 18 2026','-A','Win32',"-DMW34_PAIRED_INCLUDE=$mtResearch") (Join-Path $mtOut 'configure.log')
 InvokeTool $mtCMake @('--build',$mtBuild,'--config','Release','--verbose') (Join-Path $mtOut 'build.log')
 $mtWorker=Join-Path $mtBuild 'Release/mw34_matherr_reference.exe';InvokeTool $mtWorker @('--check-hash') (Join-Path $mtOut 'hash.log');foreach($path in $mtSources.Keys){if((Hash $path) -ne $mtSources[$path]){throw 'Original source changed during build'}};$mtPassed=$true
}catch{$mtFailure=$_.Exception.Message;$_|Out-String|Set-Content -LiteralPath (Join-Path $mtOut 'failure.txt');throw}finally{
 $mtArtifacts=[ordered]@{};foreach($file in @(Get-ChildItem -LiteralPath $mtOut -File -Recurse;Get-ChildItem -LiteralPath $mtResearch -File -Recurse;if(Test-Path -LiteralPath $mtBuild){Get-ChildItem -LiteralPath $mtBuild -File -Recurse|Where-Object {$_.Extension -in @('.exe','.obj','.lib','.txt','.cmake','.vcxproj','.props','.json','.tlog')}})|Sort-Object FullName){$mtArtifacts[$file.FullName]=Hash $file.FullName}
 $mtTools=[ordered]@{};foreach($tool in @($mtCMake,(Get-Process -Id $PID).Path,(Join-Path $mtVS 'Common7/Tools/Microsoft.VisualStudio.DevShell.dll'),(Join-Path $mtVS 'MSBuild/Current/Bin/amd64/MSBuild.exe'))+@('cl.exe','link.exe','rc.exe','ml.exe'|ForEach-Object {(Get-Command $_ -ErrorAction SilentlyContinue).Source})){if($tool -and (Test-Path -LiteralPath $tool)){$mtTools[$tool]=Hash $tool}}
 @{passed=$mtPassed;failure=$mtFailure;scope='Actual original isolated17-byte four-instruction leaf; native comparison pending, no callback invocation';source_files=$mtSources;literal_source_copies=@($mtCopies);tool_files=$mtTools;artifacts=$mtArtifacts;commands=@($mtCommands);worker=$mtWorker;provider_path=$mtProvider;provider_sha256=(Hash $mtProvider);pack_path=(Join-Path $mtResearch 'pack.bin');pack_sha256=(Hash (Join-Path $mtResearch 'pack.bin'));whole_M4_complete=$false}|ConvertTo-Json -Depth 16|Set-Content -Encoding utf8 -LiteralPath (Join-Path $mtOut 'build.json')
}
